questionvariables.text:
/* Randomize mean and standard deviation */
mu : rand([20, 25, 30, 35, 40, 45, 50]);
sigma : rand([2, 3, 4, 5]);

/* Part a variables (1 or 2 standard deviations) */
k_a : rand([1, 2]);
lower_a : mu - k_a * sigma;
upper_a : mu + k_a * sigma;

/* Use exact fractions for STACK calculations, and strings for display to avoid float drift */
ta1 : if k_a = 1 then 68/100 else 95/100;
pct_a : if k_a = 1 then 68 else 95;
ta1_str : if k_a = 1 then "0.68" else "0.95";

/* Part b variables (1, 2, or 3 standard deviations, upper or lower tail) */
k_b : rand([1, 2, 3]);
dir_b : rand([1, 2]); /* 1 = more than, 2 = less than */
tail_word : if dir_b = 1 then "more than" else "less than";
sign_b : if dir_b = 1 then ">" else "<";
sign_math_b : if dir_b = 1 then "+" else "-";
bound_b : if dir_b = 1 then mu + k_b * sigma else mu - k_b * sigma;

/* Using exact rationals to protect the test suite from floating-point evaluation bugs */
rule_b_frac : if k_b = 1 then 68/100 elseif k_b = 2 then 95/100 else 997/1000;
rule_b_str : if k_b = 1 then "0.68" elseif k_b = 2 then "0.95" else "0.997";
pct_b_str : if k_b = 1 then "68" elseif k_b = 2 then "95" else "99.7";

ta2 : (1 - rule_b_frac) / 2;
ta2_str : if k_b = 1 then "0.16" elseif k_b = 2 then "0.025" else "0.0015";
ta2_wrong : 1 - rule_b_frac;

/* Part c variables (Expected count) */
k_c : rand([1, 2]);
lower_c : mu - k_c * sigma;
upper_c : mu + k_c * sigma;
N_pop : rand([500, 1000, 1500, 2000, 2500]);
ta3_prob : if k_c = 1 then 68/100 else 95/100;
ta3_prob_str : if k_c = 1 then "0.68" else "0.95";
ta3 : ta3_prob * N_pop;
